</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
#define REP(i,a,b) for(int i=a;i<=b;i++)
#define REV(i,a,b) for(int i=a;i>=b;i--)
using namespace std;

typedef long long ll;

const int MAX_SIZE=262144;

int L,n,k,Mo,len,bit[20],fac[MAX_SIZE],inv[MAX_SIZE],cnt[MAX_SIZE],g[20][MAX_SIZE],f[20][MAX_SIZE];

int qpow(int base,int exp) {
	int res=1;
	while (exp > 0) {
		if (exp & 1) res=(ll)res*base%Mo;
		base=(ll)base*base%Mo;
		exp>>=1;
	}
	return res;
}

void add_mod(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void sub_mod(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void transform_FWT(int *a,int length) {
	for(int size=1;size<length;size<<=1) {
		for(int start=0;start<length;start+=size<<1) {
			for(int offset=0;offset<size;offset++) {
				add_mod(a[start+offset+size],a[start+offset]);
			}
		}
	}
}
void transform_IFWT(int *a,int length) {
	for(int size=1;size<length;size<<=1) {
		for(int start=0;start<length;start+=size<<1) {
			for(int offset=0;offset<size;offset++) {
				sub_mod(a[start+offset+size],a[start+offset]);
			}
		}
	}
}

ll h[20],p[20];

void compute_log() {
	p[0]=0;
	REP(i,1,n) {
		p[i]=h[i]*i;
		REP(j,1,i-1) p[i]-=p[j]*h[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	REP(i,0,n) h[i]=(p[i]+Mo)%Mo;
}

void compute_exp() {
	p[0]=1;
	REP(i,1,n) {
		p[i]=0;
		REP(j,1,i) {
			p[i]+=h[j]*p[i-j]%Mo*j;
		}
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	REP(i,0,n) h[i]=p[i];
}

int main() {
	scanf("%d%d%d",&L,&k,&Mo);
	int total=pwr(k,L);
	if (L%2==1) {
		printf("%d\n",total);
		return 0;
	}
	fac[0]=1; REP(i,1,L) fac[i]=(ll)fac[i-1]*i%Mo;
	inv[L]=pwr(fac[L],Mo-2);
	REV(i,L-1,0) inv[i]=(ll)inv[i+1]*(i+1)%Mo;
	REP(s,1,L) cnt[s]=cnt[s^(s&-s)]+1;
	REP(i,0,18) if (L>>i&1) bit[++n]=1<<i;
	len=1<<n;
	REP(i,0,len-1) {
		int s=0;
		REP(j,1,n) if (i>>(j-1)&1) s+=bit[j];
		g[cnt[i]][i]=inv[s];
	}
	REP(i,2,n) inv[i]=(ll)(Mo-Mo/i)*inv[Mo%i]%Mo;
	REP(i,0,n) transform_FWT(g[i],len);
	REP(s,0,len-1) {
		REP(i,0,n) h[i]=g[i][s];
		compute_log();
		REP(i,0,n) h[i]=h[i]*k;
		compute_exp();
		REP(i,0,n) f[i][s]=h[i];
	}
	transform_IFWT(f[n],len);
	int answer=(ll)f[n][len-1]*fac[L]%Mo;
	answer=(total-answer+Mo)%Mo;
	printf("%d\n",answer);
	return 0;
}
